fn average_grade(grades: &Map[Str, Int]) -> Float64 {
  var sum = 0;
  var count = 0;
  for key in grades.keys() {
    sum = sum + grades.get(&key).unwrap_or(0);
    count = count + 1;
  }
  if count == 0 { return 0.0; }
  return (sum as Float64) / (count as Float64);
}

fn highest_scorer(grades: &Map[Str, Int]) -> Str {
  var max = -1;
  var name = "";
  for key in grades.keys() {
    let score = grades.get(&key).unwrap_or(0);
    if score > max {
      max = score;
      name = key;
    }
  }
  return name;
}

fn main() -> Int {
  let grades = Map[Str, Int]();
  grades.insert("Alice", 95);
  grades.insert("Bob", 87);
  grades.insert("Carol", 92);
  let avg = average_grade(&grades);
  return (avg * 10.0) as Int;
}
